ALTER POLICY rosa_orientacoes_gestor ON public.rosa_orientacoes USING(public.eh_gestor(auth.uid()) AND (tenant_id IS NOT DISTINCT FROM public.get_current_tenant_id() OR public.is_super_admin(auth.uid())));
CREATE OR REPLACE FUNCTION public.rosa_revisar(p_id uuid,p_aprovar boolean,p_texto text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.eh_gestor(auth.uid()) THEN RAISE EXCEPTION 'Somente gestor' USING ERRCODE='42501'; END IF; IF p_aprovar AND length(trim(COALESCE(p_texto,''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Orientação inválida'; END IF; UPDATE public.rosa_orientacoes SET status=CASE WHEN p_aprovar THEN 'aprovada' ELSE 'rejeitada' END,orientacao_aprovada=CASE WHEN p_aprovar THEN trim(p_texto) ELSE NULL END,revisado_por=auth.uid(),revisado_em=now(),updated_at=now() WHERE id=p_id AND (tenant_id IS NOT DISTINCT FROM public.get_current_tenant_id() OR public.is_super_admin(auth.uid())); IF NOT FOUND THEN RAISE EXCEPTION 'Sugestão indisponível'; END IF; END $$;